      }
      vars.set(name, value);
    },

    // Extra helpers used by the REPL.
    variables() {
      const out = {};
      for (const [k, v] of vars) out[k] = v;
      return out;
    },

    history() {
      return hist.map((h) => ({ ...h }));
    },

    clear() {
      vars.clear();
      userFns.clear();
      ans = 0;
      hist = [];
    },

    format(value) {
      if (value === 0) return '0';
      return String(Number(value.toPrecision(precision)));
    },
  };
